select id, session_id, event_time, max(duration_sec) over (partition by event_type, session_id order by event_time, id rows between 3 preceding and current row) as last4_max_duration_sec, avg(duration_sec) over (partition by event_type, session_id order by event_time, id rows between 3 preceding and current row) as last4_avg_duration_sec, sum(duration_sec) over (partition by event_type, session_id order by event_time, id rows between 3 preceding and current row) as last4_sum_duration_sec, cume_dist() over (partition by to_date(event_time), page order by duration_sec desc nulls last) as duration_sec_cume_dist from web_events
